"""Validate XLSX bytes generated by the HTML, using an independent XLSX reader."""
from decimal import Decimal
import json
from pathlib import Path
import subprocess
import tempfile
from zipfile import ZipFile

from openpyxl import load_workbook

ROOT=Path(__file__).resolve().parents[1]
SCRIPT=r'''
const fs=require('node:fs'),vm=require('node:vm'),{TextEncoder}=require('node:util');
const html=fs.readFileSync(process.argv[1]+'/index.html','utf8');
const core=html.match(/<script id="trip-core">([\s\S]*?)<\/script>/)[1];
const exp=html.match(/<script id="trip-export">([\s\S]*?)<\/script>/)[1];
const {C,E}=vm.runInNewContext(core+'\n'+exp+'\n({C:TripCore,E:TripExport});',{TextEncoder});
const output=process.argv[2],fixtures=[];
const base=(n=3,d=2)=>{const s=C.createTrip(n,d);s.members.forEach((m,i)=>m.name=['阿安','小晴','阿哲'][i]||'旅伴'+(i+1));return s;};
const fee=(s,d,cat,amount,parts,payer=0)=>{const e=s.days[d].expenses.find(e=>e.category===cat);Object.assign(e,{amount,participantIds:parts.map(i=>s.members[i].id),payerId:payer===null?null:s.members[payer].id});return e;};
const add=(name,s)=>{fs.writeFileSync(output+'/'+name+'.xlsx',Buffer.from(E.xlsx(s,new Date('2026-10-18T17:00:00Z'))));fixtures.push({name,state:s,summary:C.summarize(s),report:E.report(s,new Date('2026-10-18T17:00:00Z'))});};
add('blank',C.createTrip());
let s=base();fee(s,0,'breakfast','100',[0,1,2]);fee(s,0,'lunch','90',[1,2],1);fee(s,0,'dinner','70',[0,2],2);fee(s,1,'breakfast','20',[2],2);add('separate_meals_and_days',s);
s=base();s.days.forEach((d,i)=>{d.useCar=true;d.drivers=[s.members[i].id];fee(s,i,'fuel','100',[0,1,2],i);fee(s,i,'rental','120',[0,1,2],i);fee(s,i,'breakfast','90',[0,1,2],i);fee(s,i,'parking','30',[0,1,2],i);});add('drivers_and_meals',s);
s=base(4);s.days[0].useCar=true;s.days[0].drivers=s.members.slice(0,2).map(m=>m.id);fee(s,0,'fuel','100',[0,1,2,3]);add('multiple_drivers',s);
s=base();s.days[0].drivers=[s.members[0].id];fee(s,0,'fuel','100',[0,1,2]);add('no_car_warning_preserved',s);
s=base();s.days[0].useCar=true;fee(s,0,'fuel','100',[0,1,2]);add('missing_driver',s);
s=base();fee(s,0,'lunch','100',[]);fee(s,0,'dinner','1.23',[0,1,2]);fee(s,0,'other','100',[0,1,2],null);add('invalid_and_missing_participants',s);
s=base();s.members[0].name='   ';s.members[1].name='';fee(s,0,'lunch','100',[0,1,2],2);add('blank_names_excluded',s);
s=C.createTrip();s.members[0].name='A';s.members[29].name='第30位';fee(s,0,'dinner','100',[0,29],29);add('person_30',s);
s=C.example();s.members[0].name='改名後';add('rename_preserves_totals',s);
s=base();s.members[0].name='=SUM(1,2)';s.members[1].name='小晴 & <同行者>';s.days[0].name='東京/京都:*?[]\\';s.days[1].name=s.days[0].name;s.days[0].expenses[0].name='"早餐" & 點心';fee(s,0,'breakfast','100',[0,1,2]);add('safe_text_and_sheet_names',s);
s=base();fee(s,0,'breakfast','100',[0,1]);const e=C.expense('breakfast');Object.assign(e,{name:'加點早餐',amount:'30',participantIds:[s.members[1].id],payerId:s.members[1].id});s.days[0].expenses.push(e);add('duplicate_meals_independent',s);
const entry=(s,pi,type,amount,payer=null,direction=type==='payment'?'minus':'plus')=>{const e=C.ledgerEntry(s.members[pi].id);Object.assign(e,{type,amount,direction,description:'用途 & <備註>',payerId:payer===null?null:s.members[payer].id});s.ledger.push(e);return e;};
s=base();fee(s,0,'dinner','6740',[0],1);entry(s,0,'payment','10000');entry(s,0,'refund','3260');entry(s,0,'charge','350',1);entry(s,1,'adjustment','4000');entry(s,1,'adjustment','6',null,'minus');add('personal_signed_settlement',s);
s=base();entry(s,0,'charge','100');entry(s,0,'adjustment','-1');entry(s,0,'payment','200');s.members[0].name='';add('personal_blank_names_and_invalid',s);
s=base();fee(s,0,'other','6280',[0],1);entry(s,0,'adjustment','4000');s.members[0].name='=HYPERLINK(1)';add('personal_literal_purpose_and_name',s);
fs.writeFileSync(output+'/fixtures.json',JSON.stringify(fixtures));
'''


def units(value):
    assert isinstance(value,(int,float)) and not isinstance(value,bool),value
    raw=Decimal(str(value))*10
    assert raw==raw.to_integral(),value
    return int(raw)


def main():
    out=Path(tempfile.mkdtemp(prefix='travel-export-'))
    subprocess.run(['node','-e',SCRIPT,str(ROOT),str(out)],check=True)
    fixtures=json.loads((out/'fixtures.json').read_text())
    for f in fixtures:
        file=out/(f['name']+'.xlsx')
        with ZipFile(file) as z:
            assert z.testzip() is None
            assert not any('externalLinks' in name for name in z.namelist())
        wb=load_workbook(file,data_only=False)
        assert len(wb.sheetnames)==len(set(n.casefold() for n in wb.sheetnames))
        assert all(len(n.encode('utf-16-le'))//2<=31 and not any(c in n for c in '\\/*?:[]') for n in wb.sheetnames)
        assert not any(c.data_type=='f' for sh in wb for row in sh for c in row)
        # Check every report cell against the generated table, including sheet order / empty merged cells.
        assert wb.sheetnames==[s['name'] for s in f['report']]
        for table in f['report']:
            sh=wb[table['name']]
            for r,row in enumerate(table['rows'],1):
                for c,entry in enumerate(row,1):
                    expected=entry['value']
                    actual=sh.cell(r,c).value
                    if expected=='':assert actual in ('',None),(f['name'],sh.title,r,c,actual)
                    else:assert actual==expected,(f['name'],sh.title,r,c,actual,expected)
        s=f['state'];summary=f['summary'];ov=wb['整趟總覽']
        assert units(ov['B3'].value)==summary['total']
        assert units(ov['D3'].value)==summary['allocated']
        assert units(ov['F3'].value)==summary['difference']
        assert ov['H3'].value==len(summary['issues'])
        assert '2026/10/19' in ov['B2'].value,ov['B2'].value
        named=[m for m in s['members'] if m['name'].strip()]
        for i,p in enumerate(summary['people']):
            assert ov.cell(7+i,1).value==p['name']
            for ci,key in enumerate(['meals','fuel','rental','other','personal','adjustment','total','advanced','paid','refunded','pay','receive'],2):
                assert units(ov.cell(7+i,ci).value)==p[key],(f['name'],p['id'],key)
        for di,day in enumerate(s['days']):
            sh=wb.worksheets[2+di]
            assert sh.freeze_panes=='C13'
            for ei,e in enumerate(day['expenses']):
                result=next(r for r in summary['expenses'] if r['expenseId']==e['id'])
                total=0
                for mi,member in enumerate(named):
                    r=13+mi
                    assert sh.cell(r,1).value==member['name']
                    assert sh.cell(r,3+2*ei).value==('參與' if member['id'] in e['participantIds'] else '未參與')
                    actual=units(sh.cell(r,4+2*ei).value)
                    assert actual==result['shares'][member['id']]
                    total+=actual
                assert total==result['allocated']
        meal_rows=list(wb['每餐參與名單'].iter_rows(min_row=4,values_only=True))
        expected_meals=[(day,e) for day in s['days'] for e in day['expenses'] if e['category'] in ['breakfast','lunch','dinner']]
        assert len(meal_rows)==len(expected_meals)
        for row,(day,e) in zip(meal_rows,expected_meals):
            expected='、'.join(m['name'] for m in named if m['id'] in e['participantIds']) or '尚未勾選'
            assert row[0]==day['name'] and row[1]==e['name'] and row[4]==expected
        personal=wb['個人紀錄']
        assert personal.max_row==3+len(s['ledger'])
        for i,e in enumerate(s['ledger'],4):
            r=next(r for r in summary['ledgerResults'] if r['id']==e['id'])
            assert personal.cell(i,3).value==e['description']
            assert personal.cell(i,4).value==('－ 扣抵' if e['direction']=='minus' else '＋ 加收')
            if r['amountValid']:
                assert units(personal.cell(i,5).value)==r['units']
                assert units(personal.cell(i,7).value)==r['units']*(-1 if e['direction']=='minus' else 1)
        advance=wb['代墊明細']
        assert advance.max_row==3+len(summary['advances'])
        for i,a in enumerate(summary['advances'],4):
            assert advance.cell(i,2).value==a['label']
            assert units(advance.cell(i,3).value)==a['units']
        if f['name']=='safe_text_and_sheet_names':
            assert ov['A7'].value=='=SUM(1,2)' and ov['A7'].data_type=='s'
        print('PASS:',f['name'],flush=True)
    (out/'report.json').write_text(json.dumps({'passed':[f['name'] for f in fixtures],'count':len(fixtures)},ensure_ascii=False,indent=2))
    print(f'\n{len(fixtures)} XLSX export scenarios passed. Artifacts: {out}',flush=True)


if __name__=='__main__':
    main()
